import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectFieldError, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlCount } from '../../support/api.js';

test.describe('SF-219 Sales Rep enters syntactically invalid email — Save is blocked and error shown on Email field', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-048 Sales Rep enters syntactically invalid email — Save is blocked and error shown on Email field',
    { tag: ['@negative', '@P2', '@SF-219', '@persona:sales-rep', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-048',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const contactFirstname = data.unique('contact-firstname');
      await data.create('account-contact', ['Account']);
      await test.step('1. Navigate to the Account record page and click New Contact', async () => {
        // Expected (DECLARED_CONFIG; SF-219#AC3, OC-004, Field:Contact.Email): New Contact modal opens with required fields visible
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step("2. Enter Last Name 'Doe' and Email 'john.example.com' (missing @), then click Save", async () => {
        // Expected (DECLARED_CONFIG; SF-219#AC3, OC-004, Field:Contact.Email, BRD-CON-012#BR-03): Save is blocked; an inline error appears on the Email field indicating the address format is invalid; Contact is not created
        await newContactDialog.lastName.fill('Doe');
        await newContactDialog.email.fill('john.example.com');
        await newContactDialog.firstName.fill(contactFirstname);
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectFieldError(newContactDialog.email);
        expect(await soqlCount(sf, 'Contact', 'FirstName', contactFirstname)).toBe(0);
      });
      await test.step('3. Verify regression marker for MTC-003 — re-execute the same invalid-email step and confirm behaviour unchanged', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC3): Save remains blocked with the same inline error on Email; no regression in validation behaviour
        await newContactDialog.email.clear();
        await newContactDialog.email.fill('john.example.com');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectFieldError(newContactDialog.email);
        expect(await soqlCount(sf, 'Contact', 'FirstName', contactFirstname)).toBe(0);
      });
    },
  );
});
